"Sur iPhone : ajoute Vezoria à l’écran d’accueil (Safari → Partager → « Sur l’écran d’accueil ») et ouvre-la de là. Garde aussi une 💾 sauvegarde complète de temps en temps.":"iPhone では：Vezoria をホーム画面に追加（Safari →共有→「ホーム画面に追加」）して、そこから開いてね。ときどき 💾 フルバックアップもしておこう。",
"Installe Vezoria (Google Play ou « Installer l’appli ») et ouvre-la souvent : Android protège alors son stockage. Garde aussi une 💾 sauvegarde complète de temps en temps.":"Vezoria をインストール（Google Play または「アプリをインストール」）してよく開いてね：そうすると Android がストレージを保護します。ときどき 💾 フルバックアップもしておこう。",
"🧹 Libérer de la place":"🧹 空き容量を増やす",
"Pour les voyages terminés ({0}), les grandes photos déjà envoyées sur le serveur sont retirées de ce téléphone. Les vignettes restent : la grille et le film s’affichent toujours, et la grande photo revient du serveur, en version allégée, quand tu l’ouvres (il faut du réseau). Les photos pas encore envoyées ne sont jamais touchées.":"終わった旅行（{0}）では、すでにサーバーに送った大きな写真をこのスマホから削除します。サムネイルは残るので、グリッドやムービーはそのまま表示され、大きな写真は開いたときに軽量版としてサーバーから戻ります（ネット接続が必要）。まだ送っていない写真には一切触れません。",
"Retirer de ce téléphone les grandes photos des voyages terminés déjà sur le serveur ? Les vignettes restent, et chaque grande photo revient quand tu l’ouvres.":"終わった旅行のうち、サーバーにある大きな写真をこのスマホから削除しますか？サムネイルは残り、大きな写真は開いたときに戻ります。",
"🧹 {0} / {1}…":"🧹 {0} / {1}…",
"✅ {0} grande(s) photo(s) retirée(s) de ce téléphone · {1} Mo libérés.":"✅ このスマホから大きな写真を {0} 枚削除 · {1} MB 空きました。",
"Rien à libérer pour le moment (photos pas encore envoyées, ou déjà libérées).":"今は空けられる容量がありません（写真が未送信、またはすでに削除済み）。",
