"📦 Place photos de ce carnet pleine sur le serveur : les photos restantes restent sur ce téléphone, rien n’est perdu.":"📦 サーバー上のこの旅行手帳の写真容量がいっぱいです：残りの写真はこのスマホに残り、何も失われません。",
