"Une note sur Google Play aide d’autres voyageurs à trouver l’appli, et m’encourage à continuer à l’améliorer. Ça prend 30 secondes. Merci 🙏":"Google Play での評価は、ほかの旅行者がアプリを見つける助けになり、改善を続ける励みにもなります。30 秒で終わります。ありがとう 🙏",
