"Crée le code de ce voyage et invite tes compagnons : ils ne voient que ce voyage, le reste reste privé.":"この旅行のコードを作って仲間を招待：仲間に見えるのはこの旅行だけで、ほかは非公開のままです。",
"🔗 Créer le code et inviter":"🔗 コードを作成して招待",
"🤝 Rejoindre un voyage avec un code":"🤝 コードで旅行に参加",
"Rien n’est en ligne pour l’instant : tes voyages restent sur ce téléphone.":"まだ何もオンラインにありません：旅行はこのスマホの中だけです。",
"Créer ton code principal ?\n\nTous tes voyages seront sauvegardés sur le serveur, chiffrés sur ce téléphone : personne d’autre ne peut les lire. Garde bien ce code : c’est lui qui ouvre ton carnet sur un autre appareil.":"メインコードを作成しますか？\n\nすべての旅行がサーバーにバックアップされ、このスマホで暗号化されます：ほかの誰も読めません。このコードは大切に保管してください：別の端末で手帳を開く鍵になります。",
