"Le carnet est la première esquisse de Vezoria. C’est grâce à vos critiques sur le carnet que Vezoria avance : continuez à tester et à dire ce que vous en pensez.":"旅の手帳は Vezoria の最初の下書きです。手帳へのみなさんの意見のおかげで Vezoria は進化しています：これからも試して、感想を聞かせてください。",
