"👀 Des abonnés, comme Polarsteps : tes proches suivent le voyage (photos en vignettes et récits), mettent des ❤️ et des commentaires.":"👀 Polarsteps のようなフォロワー機能：家族や友人が旅行をフォロー（写真のサムネイルと旅日記）し、❤️ やコメントを付けられます。",
"👥 Une fenêtre « Abonnés & partages », avec une pastille dès qu’il y a du nouveau.":"👥 「フォロワーと共有」画面。新着があるとバッジが付きます。",
"🛰️ Ta route sur la carte pour tes abonnés, seulement si tu l’actives.":"🛰️ オンにした場合だけ、フォロワーの地図にあなたのルートを表示。",
"🚩 Signaler, bloquer ou masquer quelqu’un, et créer un nouveau lien abonné.":"🚩 報告、ブロック、非表示、新しいフォロワーリンクの作成。",
"🎬 Le film du voyage en musique (11 musiques), avec la carte zoomée région par région.":"🎬 音楽付きの旅行ムービー（11曲）、地域ごとにズームする地図付き。",
"📷 « Ranger mes photos » : les photos se placent toutes seules au bon jour et au bon endroit.":"📷 「写真を整理」：写真が自動で正しい日と場所に並びます。",
"🗺️ Le programme et le voyage en cours sur la carte.":"🗺️ 予定と進行中の旅行を地図で。",
"💱 La conversion des devises dans les dépenses et les tickets.":"💱 支出とレシートの通貨換算。",
"🎨 Des couleurs pour chaque moment : préparation, voyage en cours, souvenirs.":"🎨 準備・旅行中・思い出、それぞれの時期に合わせた色。",
"☁️ Une synchro plus économe, voyage par voyage, avec l’état de l’envoi en un coup d’œil.":"☁️ 旅行ごとの省データ同期、送信状況がひと目でわかります。",
"🔐 Un chiffrement renforcé dans la version finale.":"🔐 最終版では暗号化を強化。",
"🎓 Un nouveau tuto vidéo de 3 minutes.":"🎓 新しい3分間の動画チュートリアル。",
"🛫 Escale (recherche de vols, Radar des prix) : pour respecter les règles de Google Play, Escale ne sera pas dans la version finale de Vezoria. Le module fait appel à trop de services extérieurs pour être publié.":"🛫 Escale（航空券検索、価格レーダー）：Google Play の規約を守るため、Escale は Vezoria の最終版には含まれません。このモジュールは外部サービスに頼りすぎていて公開できないためです。",
"🔕 Aucune notification : Vezoria ne t’envoie rien.":"🔕 通知はなし：Vezoria からは何も送りません。",
"📥 L’import depuis Polarsteps n’est pas encore dans Vezoria.":"📥 Polarsteps からのインポートはまだ Vezoria にありません。",
"Cette version test garde le stockage du carnet : même serveur, mêmes codes. Tes compagnons restés sur le carnet voient ce que tu fais dans Vezoria, et inversement.":"このテスト版は手帳と同じ保存先を使います：同じサーバー、同じコード。手帳を使い続ける仲間にも Vezoria での操作が見え、その逆も同様です。",
"Avant la première ouverture de Vezoria, une copie de sauvegarde de ton carnet est gardée sur ce téléphone.":"Vezoria を初めて開く前に、手帳のバックアップがこのスマホに保存されます。",
"📱 Vezoria sera sur Google Play (Android) et en appli web sur iPhone.":"📱 Vezoria は Google Play（Android）と、iPhone ではウェブアプリとして提供予定です。",
