"🚩 Signaler ce commentaire":"🚩 このコメントを報告",
"🚫 Bloquer {0} (pour tous tes abonnés)":"🚫 {0} をブロック（すべてのフォロワーに対して）",
"🙈 Masquer ce que publie {0}":"🙈 {0} の投稿を非表示",
"Supprimer ce commentaire ?":"このコメントを削除しますか？",
"Masquer les commentaires et ❤️ de cette personne sur ce téléphone ?":"このスマホでこの人のコメントと ❤️ を非表示にしますか？",
"Bloquer {0} ?\n\nSes commentaires et ❤️ sont masqués pour tous tes abonnés et elle est retirée de la liste.\nPour l’empêcher aussi de voir tes souvenirs, touche ensuite « 🔁 Nouveau lien abonné » et renvoie le lien seulement aux personnes de ton choix.":"{0} をブロックしますか？\n\nこの人のコメントと ❤️ はすべてのフォロワーから見えなくなり、リストからも外されます。\nあなたの思い出も見られないようにするには、続けて「🔁 新しいフォロワーリンク」をタップし、選んだ人にだけリンクを送り直してください。",
"Créer un nouveau lien abonné ?\n\nL’ancien lien ne marchera plus : plus personne ne voit tes souvenirs tant que tu n’as pas renvoyé le nouveau lien. Les ❤️ et commentaires passés sont effacés.":"新しいフォロワーリンクを作成しますか？\n\n古いリンクは使えなくなります：新しいリンクを送るまで、誰もあなたの思い出を見られません。これまでの ❤️ とコメントは消去されます。",
"Pourquoi signales-tu ce contenu ? (contenu illicite, harcèlement, nudité, violence, autre…)":"このコンテンツを報告する理由は？（違法なコンテンツ、嫌がらせ、ヌード、暴力、その他…）",
