"Pour partager un seul voyage, inutile : dans le voyage, touche Partager. Seul ce voyage est alors stocké sur le serveur, tes autres voyages restent sur ton téléphone.":"1つの旅行だけを共有するなら不要です：旅行の中で「共有」をタップ。その旅行だけがサーバーに保存され、ほかの旅行はスマホに残ります。",
