"Tu découvres, tu profites, tu prends des photos. L’appli t’accompagne tout au long du chemin.":"探検して、楽しんで、写真を撮る。アプリが道中ずっと寄り添います。",
"Tu revis, tu partages, tu gardes.":"思い返して、共有して、残す。",
"Ton voyage devient un carnet vivant : photos, notes, émotions, et même les bons plans pour la prochaine fois.":"旅が生きた手帳に：写真、メモ、感動、そして次回のためのお得情報まで。",
