"Parce que les plus beaux voyages se vivent deux fois.":"最高の旅は、二度味わえるから。",
"Chaque dépense raconte un bout du voyage.":"支出のひとつひとつが旅の一部を語る。",
"Une valise bien faite, un esprit léger.":"きちんと詰めたスーツケースで、心は軽やかに。",
