"Créer un nouveau code pour « {0} » ?\n\nLe voyage, ses fiches et ses photos repartent sur le serveur sous ce nouveau code. Les autres téléphones doivent ensuite le rejoindre avec le nouveau code (Mes voyages → Rejoindre un voyage partagé).":"「{0}」の新しいコードを作成しますか？\n\n旅行、項目、写真がこの新しいコードでサーバーに再送信されます。その後、ほかのスマホは新しいコードで参加し直す必要があります（マイ旅行 → 共有旅行に参加）。",
"⚠️ Le voyage n’a pas pu être envoyé sous le nouveau code : {0}\nRéessaie avec « Tout renvoyer » quand la connexion est bonne.":"⚠️ 新しいコードで旅行を送信できませんでした：{0}\n接続が安定しているときに「すべて再送信」でもう一度お試しください。",
"✅ Voyage en ligne : le code peut être donné":"✅ 旅行はオンラインです：コードを共有できます",
"Ce voyage avait déjà un code (effacé du serveur, par exemple) ? Colle-le ici pour le réutiliser : les autres téléphones le retrouveront.\nSinon laisse vide : un nouveau code sera créé.":"この旅行には以前コードがありましたか（サーバーから削除された場合など）？ここに貼り付けると再利用でき、ほかのスマホからも再び見つかります。\n不要なら空欄のまま：新しいコードが作成されます。",
"🗑 Supprimé du serveur : {0} fiche(s) et {1} photo(s).\nTes données restent sur ce téléphone.\n\nGarder le code sur ce téléphone ?\nOK = je garde le code : tu pourras tout renvoyer plus tard avec le même code (bouton « Tout renvoyer »).\nAnnuler = j’oublie ce code ici.":"🗑 サーバーから削除しました：項目 {0} 件、写真 {1} 枚。\nデータはこのスマホに残ります。\n\nこのスマホにコードを残しますか？\nOK = コードを残す：あとで同じコードですべて再送信できます（「すべて再送信」ボタン）。\nキャンセル = このコードをここで忘れる。",
"Le code est gardé. Pour tout remettre sur le serveur : {0} → « Tout renvoyer ».":"コードは保持されています。サーバーにすべて戻すには：{0} →「すべて再送信」。",
"Mes voyages → le voyage → code":"マイ旅行 → 旅行 → コード",
"📤 Voyage ou photos non arrivés ?":"📤 旅行や写真が届いていない？",
