"Hors connexion : cette ville n’a pas encore été explorée.":"オフライン：この街はまだ探索していません。",
"Impossible de charger le guide pour l’instant. Réessaie dans un moment.":"ガイドを読み込めませんでした。少し後でもう一度お試しください。",
"Rien trouvé pour cette ville pour l’instant.":"この街の情報はまだ見つかりません。",
