"Le globe n’a pas pu se charger. Vérifie ta connexion et réessaie.":"地球儀を読み込めませんでした。接続を確認して、もう一度お試しください。",
"Pour le survol, ajoute des souvenirs avec un lieu ou des hébergements avec une ville.":"フライオーバーには、場所付きの思い出か、都市付きの宿泊を追加してください。",
